# Spec for the axis_fir_accel explorer. Every block, wire and rule comes from rtl/ (axis_fir_top and everything under it), tb/, verif/ and results/.
def N(x, y, w, h, t, s, l=(), ext=False, ver=False, stage="", file="", role="", resp=(), inp=(), out=(), deps=(), code=""):
    d = dict(x=x, y=y, w=w, h=h, t=t, s=s, l=list(l), stage=stage, file=file, role=role, resp=list(resp), code=code)
    d["in"] = list(inp); d["out"] = list(out); d["deps"] = list(deps)
    if ext: d["ext"] = 1
    if ver: d["ver"] = 1
    return d


def E(id, frm, to, typ, label, pts, desc=""):
    d = {"id": id, "from": frm, "to": to, "type": typ, "label": label, "pts": pts}
    if desc: d["desc"] = desc
    return d


